function countTotalColumnCards(columnSizes) {
    return columnSizes.reduce((sum, n) => sum + n, 0);
}

const MAX_SETTINGS_LEVEL = Math.max(...Object.keys(LEVEL_SETTINGS).map(Number));

function getLevelSettings(level) {
    const settings = LEVEL_SETTINGS[level] || LEVEL_SETTINGS[MAX_SETTINGS_LEVEL];
    const totalColumnCards = countTotalColumnCards(settings.columnSizes);
    return {
        numCategories: settings.numCategories,
        maxSlots: settings.maxSlots,
        maxSteps: settings.maxSteps,
        numColumns: settings.numColumns,
        columnSizes: settings.columnSizes,
        totalColumnCards,
    };
}
